"""Calculate the fleet's real energy yield for the UTC day 2024-03-15."""

from collections import Counter
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATA_DIR = Path("/app/dataset")
DAY_START = datetime(2024, 3, 15, tzinfo=timezone.utc)
DAY_END = DAY_START + timedelta(days=1)
BTU_TO_KWH = 0.0002930710701722222

# These are the completed windows in maintenance_notes.txt. The cancelled
# Sakura inspection is deliberately absent.
COMPLETED_MAINTENANCE = {
    "FARM_C": [(datetime(2024, 3, 16, 8), datetime(2024, 3, 16, 12))],
    "FARM_F": [(datetime(2024, 3, 15, 12), datetime(2024, 3, 15, 14))],
}


def parse_local_timestamp(value):
    """Only accept the two complete date/time formats used by the exports."""
    if not isinstance(value, str):
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    return None


def parse_number(value):
    if not isinstance(value, str):
        return float("nan")
    value = value.strip()
    if "," in value:
        value = value.replace(".", "").replace(",", ".")
    try:
        return float(value)
    except ValueError:
        return float("nan")


def read_export(farm_id):
    path = DATA_DIR / f"production_{farm_id}.csv"
    encoding = "utf-16" if path.read_bytes().startswith(b"\xff\xfe") else "utf-8"
    header = path.read_text(encoding=encoding).splitlines()[3]
    separator = ";" if ";" in header else ","
    return pd.read_csv(path, encoding=encoding, skiprows=3, sep=separator, dtype=str)


def sample_hours(timestamps):
    """Find each power meter's normal cadence without filling invalid gaps."""
    ordered = sorted(set(timestamps))
    differences = [(later - earlier).total_seconds() for earlier, later in zip(ordered, ordered[1:])]
    if not differences:
        return 0.0
    return Counter(differences).most_common(1)[0][0] / 3600.0


def answer() -> dict[str, int]:
    registry = pd.read_csv(DATA_DIR / "farm_registry.csv")
    farms = pd.read_csv(DATA_DIR / "farms.csv")
    farms["farm_name"] = farms["farm_name"].str.strip().str.casefold()
    fleet = registry.merge(farms, on="farm_name", validate="one_to_one")
    with open(DATA_DIR / "sensors_calibration.json") as file:
        calibration = json.load(file)["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]

    result = {}
    for farm in fleet.itertuples(index=False):
        farm_id = farm.farm_id
        settings = calibration[farm_id]
        value_column = settings["calibration_data"]["value_column_name"]
        offset = settings["calibration_data"]["calibration_offset"]
        reading_type = settings["sensor_info"]["reading_type"].lower()
        unit = settings["sensor_info"]["unit"].lower()
        zone = ZoneInfo(farm.timezone)

        data = read_export(farm_id)
        data["_local_time"] = data.iloc[:, 0].map(parse_local_timestamp)
        data = data.dropna(subset=["_local_time"])

        # Later rows correct the earlier record at the same local timestamp.
        data = data.drop_duplicates(subset=["_local_time"], keep="last").copy()
        cadence_hours = sample_hours(data["_local_time"])
        data["_utc_time"] = data["_local_time"].map(
            lambda stamp: stamp.replace(tzinfo=zone).astimezone(timezone.utc)
        )

        # A temperature above 85 C invalidates the following 45 minutes.
        data["_temperature"] = data["inverter_temperature_C"].map(parse_number)
        spikes = data.loc[data["_temperature"] > 85.0, "_utc_time"]
        valid = (data["_utc_time"] >= DAY_START) & (data["_utc_time"] < DAY_END)
        for spike in spikes:
            valid &= ~((data["_utc_time"] > spike) & (data["_utc_time"] <= spike + timedelta(minutes=45)))

        for local_start, local_end in COMPLETED_MAINTENANCE.get(farm_id, []):
            start = local_start.replace(tzinfo=zone).astimezone(timezone.utc)
            end = local_end.replace(tzinfo=zone).astimezone(timezone.utc)
            valid &= ~((data["_utc_time"] >= start) & (data["_utc_time"] < end))

        data = data.loc[valid].copy()
        data["_true_value"] = data[value_column].map(parse_number) - offset
        data = data.loc[data["_true_value"].notna() & (data["_true_value"] >= 0)]

        if reading_type == "power":
            kwh = data["_true_value"].sum() * cadence_hours
        else:
            factor = {"wh": 0.001, "kwh": 1.0, "mwh": 1000.0, "btu": BTU_TO_KWH}[unit]
            kwh = data["_true_value"].sum() * factor
        result[farm_id] = round(float(kwh))

    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w") as file:
        json.dump(answer(), file, default=list)

